public class JSodaSurverySodaAvg {
	public static void main(String[] args) {
		//Paso 1: Definir un arreglo bidimensional de 4x10
		int[][] ratingsData = {{ 3, 4, 5, 2, 1, 4, 3, 2, 4, 4 }, 
				{ 2, 4, 3, 4, 3, 3, 2, 1, 2, 2 },
				{ 3, 5, 4, 5, 5, 3, 2, 5, 5, 5 },
				{ 1, 1, 1, 3, 1, 2, 1, 3, 2, 4 }};
		//Paso 2: Obtener las dimensiones del arreglo que almacena los datos de calificaciones
		int numSodas = ratingsData.length;
		int numRespondents = ratingsData[0].length;
		//Paso 3: Crear un arreglo para almacenar la suma de calificaciones de cada sabor de refresco
		int[] sodaSum = new int[numSodas];
		//Paso 4: Iterar sobre los refrescos 
		for (int i = 0; i < numSodas; i++) {
			//Paso 4.1: Calcular la suma de las calificaciones para el refresco i+1    
