				sodaSum[i] += ratingsData[i][j];
			}
		}
		//Paso 5: Calcular e imprimir la calificacion promedio para cada refresco
		System.out.println ("Promedios:");
		for (int i = 0; i < numSodas; i++) {
			System.out.printf("Refresco # %d : %.2f\n", (i+1), (double) sodaSum[i]/numRespondents);
		}
	}
}

